const caption = $('WF-DPV.07 - TRIGGER | Iniciar Cadastro').first().json.caption || '';
const pushName = $('WF-DPV.07 - TRIGGER | Iniciar Cadastro').first().json.pushName || '';
const step = input.step || 'novo';
const nomePadrao = pushName ? pushName.split(' ')[0] : '';
return [{
  json: {
    phone, caption: caption.trim(), step,
    nome_temp: input.nome_temp || '',
    email_temp: input.email_temp || '',
    tentativas: input.tentativas || 0,
    pushName, nomePadrao
  }
}];

