parameters.jsCode:
const phone = $('WF-DPV.07 - TRIGGER | Iniciar Cadastro').first().json.phone;
const codigoDigitado = $('WF-DPV.07 - TRIGGER | Iniciar Cadastro').first().json.caption.trim();
const db = $input.first().json;
const codigoCorreto = db.codigo === codigoDigitado;
const expirado = new Date(db.codigo_expira) < new Date();
const tentativas = (db.tentativas || 0) + 1;
const bloqueado = tentativas > 5;
return [{ json: { phone, codigoCorreto, expirado, bloqueado, tentativas, nome: db.nome_temp, email: db.email_temp } }];

const cpf = String($json.caption || '').replace(/[^0-9]/g, '');
const valido = cpf.length === 11 || cpf.length === 14;
return [{ json: { ...$json, cpf_cnpj: cpf, cpf_valido: valido, cpf_erro: valido ? null : 'CPF/CNPJ invalido: deve ter 11 ou 14 digitos (recebido: ' + cpf.length + ')' } }];

const input = String($json.caption || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
let tipo = null;
if (input === '1' || input === 'empresa' || input.startsWith('empr')) tipo = 'empresa';
else if (input === '2' || input === 'particular' || input.startsWith('part')) tipo = 'particular';
return [{ json: { ...$json, tipo_pagador: tipo || 'particular' } }];

const input = String($json.caption || '').trim().toLowerCase().replace(/[^a-z]/g, '');
let forma = null;
if (input === 'a' || input === 'cartao' || input.startsWith('cart')) forma = 'cartao';
else if (input === 'b' || input === 'dinheiro' || input.startsWith('dinh')) forma = 'dinheiro';
return [{ json: { ...$json, forma_pagamento: forma || 'cartao' } }];

